UPDATE sys_imp_tmp
SET pass_count = #{passCount}
    ,fail_count = #{failCount}
    ,chk_rslt = #{chkRslt}
    ,chk_dscr = #{chkDscr}
    ,result_json = #{resultJson}
    ,updt_time = #{updtTime}
WHERE imp_id = #{impId} AND biz_type = 'fund_pool_excel' AND is_deleted = 0

UPDATE sys_imp_tmp
SET save_rslt = #{saveRslt}
    ,save_dscr = #{saveDscr}
    ,result_json = #{resultJson}
    ,fld011 = #{fld011}
    ,fld012 = #{fld012}
    ,updt_time = #{updtTime}
WHERE imp_id = #{impId} AND biz_type = 'fund_pool_excel' AND is_deleted = 0

UPDATE sys_imp_tmp_detl
SET chk_rslt = #{chkRslt}
    ,chk_dscr = #{chkDscr}
    ,fld002 = #{fld002}
    ,fld009 = #{fld009}
    ,fld010 = #{fld010}
    ,updt_time = #{updtTime}
WHERE id = #{id} AND imp_id = #{impId} AND is_deleted = 0

UPDATE sys_imp_tmp_detl
SET save_rslt = #{saveRslt}
    ,save_dscr = #{saveDscr}
    ,updt_time = #{updtTime}
WHERE id = #{id} AND imp_id = #{impId} AND is_deleted = 0
